import 'package:flutter/material.dart';import '../services/vault_store.dart';import '../models/vault_item.dart';
class HistoryScreen extends StatefulWidget{const HistoryScreen({super.key});@override State<HistoryScreen> createState()=>_HistoryState();}
class _HistoryState extends State<HistoryScreen>{@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Activity')) ,body:FutureBuilder<List<VaultItem>>(future:VaultStore.items(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const Center(child:Text('No activity yet'));return ListView(children:s.data!.map((v)=>ListTile(leading:const Icon(Icons.history),title:Text(v.name),subtitle:Text('${v.method} · ${v.created.toLocal()}'))).toList());}));}
